      k-=fat;
      const st=stOf(p);if(st==="sakat"||st==="hasta"){k=Math.min(k,40);parts.push([STATUS[st].label,"şu an oynayamıyor",0])}
      k=Math.round(Math.max(20,Math.min(100,k)));
