// iddia cümleleri meydan okuyanın ağzındandır
const DU_K={gol:"Senden çok gol atarım",asist:"Senden çok asist yaparım",ga:"Senden çok skora katkı yaparım",km:"Senden çok koşarım",pa:"Senden çok pas arası yaparım",tk:"Senden çok top kaparım",pas:"Senden çok pas yaparım",isa:"Paslarım seninkinden isabetli olur",tm:"Bu maçı biz alırız",kl2:"Sana en az 2 gol atarım",kl0:"Bana gol atamazsın"};
const DU_T={gol:"Gol düellosu",asist:"Asist düellosu",ga:"Skor katkısı düellosu",km:"Koşu düellosu",pa:"Pas arası düellosu",tk:"Top kapma düellosu",pas:"Pas düellosu",isa:"İsabet düellosu",tm:"Takım düellosu",kl2:"Kaleci düellosu",kl0:"Kaleci düellosu"};
const DU_TR={km:1,pa:1,tk:1,pas:1,isa:1};const duK=k=>DU_K[k]||"Notum seninkinden yüksek olur";const duT=k=>DU_T[k]||"Düello";
const DU_ERR={yetki:"Bu hak yalnızca düello kralında",value:"Bu oyuncu seçilemiyor",closed:"Maç başladı, düello kapandı",dolu:"3 teklif hakkın doldu",rdolu:"Rakibin 3 düello kabul etmiş, yeri yok",kdolu:"3 kabul hakkın doldu",var:"Bu rakiple bu konuda zaten düellon var",uye:"Bu oyuncunun hesabı yok",kadro:"İkiniz de bu maçın kadrosunda olmalısınız",takim:"Bu düello için karşı takımlarda olmalısınız",kaleci:"Bu düello kaleciyle yapılır",yok:"Düello bulunamadı",auth:"Önce giriş yapmalısın",value:"Rakip ve iddia seç"};
const DU_IC='<svg viewBox="0 0 24 24" fill="none" stroke="#06222A" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 4l6 8-6 8M18 4l-6 8 6 8"/></svg>';
function duLoad(force){if(!isMember()||S.fol||!myPid())return;if(DU.at===-1||(!force&&Date.now()-DU.at<60000))return;DU.at=-1;
  rpc("duel_list",{}).then(r=>{DU.at=Date.now();if(r&&r.ok){const o=JSON.stringify([DU.rows,DU.kings]);DU.rows=r.rows||[];DU.kings=r.kings||[];if(o!==JSON.stringify([DU.rows,DU.kings])&&S.tab==="mac"&&!S.sheet&&!S.view)render(true)}setTimeout(sonucPop,600)}).catch(()=>{DU.at=Date.now()-50000;setTimeout(sonucPop,600)})}
function duVal(m,d,id){const k=d.k;if(k==="not"){const r=mDone(m)&&S.mInfo[m.id]&&S.mInfo[m.id].pts[id];return r&&isFinite(r.pts)?Math.round(r.pts*10)/10:null}if(m.state!=="bitti"||m.score_a==null)return null;
  if(DU_TR[k]){const t=trkOf(m,id);const v=t?+t[k]:NaN;return isFinite(v)?v:null}const o=(m.stats||{})[id]||{};const g=+o.g||0,a=+o.a||0;
  if(k==="tm"){const sd=sideOf(m,id);return sd==="A"?+m.score_a||0:sd==="B"?+m.score_b||0:null}return k==="gol"?g:k==="asist"?a:k==="ga"?g+a:null}
function duRes(m,d,me){const ot=d.a===me?d.b:d.a;
  if(d.k==="kl2"||d.k==="kl0"){if(m.state!=="bitti"||m.score_a==null)return null;const sh=d.k==="kl2"?d.a:d.b;const g=+((m.stats||{})[sh]||{}).g||0;const shWin=d.k==="kl2"?g>=2:g>=1;const iSh=me===sh;return{x:iSh?g:null,y:iSh?null:g,r:(iSh?shWin:!shWin)?"G":"M"}}
  const x=duVal(m,d,me),y=duVal(m,d,ot);if(x==null||y==null)return null;return{x,y,r:x>y?"G":x<y?"M":"B"}}
// bu iki oyuncu arasında açılabilecek iddialar: takım ve kaleci düelloları yalnızca karşı takımlarda
function duKinds(m,me,ot){const sa=sideOf(m,me),sb=sideOf(m,ot);const K=["gol","asist","ga","km","pa","tk","pas","isa"];if(sa&&sb&&sa!==sb){K.push("tm");const kMe=roleIn(m,me,sa)==="KL",kOt=roleIn(m,ot,sb)==="KL";if(kOt&&!kMe)K.push("kl2");if(kMe&&!kOt)K.push("kl0")}return K}
function duRec(me){let w=0,l=0;(DU.rows||[]).forEach(d=>{if(d.s!=="kabul"||(d.a!==me&&d.b!==me))return;const m=S.matches.find(x=>x.id===d.m);const r=m&&duRes(m,d,me);if(r){if(r.r==="G")w++;else if(r.r==="M")l++}});return{w,l}}
const duNum=(d,v)=>v==null?"":d.k==="not"||d.k==="km"?fN(v):d.k==="isa"?"%"+v:v;const duBek=d=>DU_TR[d.k]?"Saha verisi bekleniyor":d.k==="not"?"Notlar bekleniyor":"Skor bekleniyor";
const duOpen=m=>m.state==="takim"&&Date.now()<matchTs(m);
const DU_MAX=3;
function duMine(m,me){const pl=plAll(m);return (DU.rows||[]).filter(x=>x.m===m.id&&(x.a===me||x.b===me)&&pl.includes(x.a)&&pl.includes(x.b))}
/* kadro açıklanmadan önce: düello görünür ama kapalıdır */
function duelWait(){const me=myPid();if(!isMember()||S.fol||!me)return"";duLoad();const rc=DU.rows?duRec(me):{w:"–",l:"–"};
  return th2Kart("thC duw",DU_IC,"Düello","Kadro bekleniyor",[["Galibiyet",rc.w],["Yenilgi",rc.l]],`<span class="duw-n">Kadrolar açıklanınca açılır</span>`)}
function duelCard(m){const me=myPid();if(!isMember()||S.fol||!me||isExt(m)||m.state==="kayit")return"";duLoad();if(!DU.rows)return"";if(!plAll(m).includes(me))return"";
  const M=esc(m.id);const open=duOpen(m);const D=duMine(m,me).filter(d=>d.s!=="red"&&d.s!=="iptal");
  const B=(act,t)=>`<button class="thk-c" data-act="${act}" data-id="${M}">${t}</button>`;
  if(open){const inc=D.filter(d=>d.s==="bekliyor"&&d.b===me).length,pen=D.filter(d=>d.s==="bekliyor").length;const out=D.filter(d=>d.a===me).length,acc=D.filter(d=>d.b===me&&d.s==="kabul").length;
    if(!D.length){const rc=duRec(me);return th2Kart("thC",DU_IC,"Düello",DU_MAX+" teklif hakkın var",[["Galibiyet",rc.w],["Yenilgi",rc.l]],B("duNew","Meydan oku"))}
    return th2Kart("thC",DU_IC,"Düello",inc?inc+" meydan okuma":pen?"Yanıt bekleniyor":"Maçta belli olur",[["Teklifin",out+"/"+DU_MAX],["Kabul ettiğin",acc+"/"+DU_MAX]],B("duList",inc?"Yanıtla":"Düellolar"))}
  const A=D.filter(d=>d.s==="kabul");if(!A.length)return"";const R=A.map(d=>duRes(m,d,me));const dn=R.filter(Boolean);
  if(!dn.length)return th2Kart("thC",DU_IC,"Düello",m.state==="bitti"?"Sonuç bekleniyor":"Maçta belli olur",[["Düello",A.length],["Sonuçlanan",0]],B("duList","Düellolar"));
  const w=dn.filter(r=>r.r==="G").length,l=dn.filter(r=>r.r==="M").length;
  return th2Kart("thC",DU_IC,"Düello",dn.length<A.length?`${dn.length}/${A.length} sonuçlandı`:w>l?"Önde bitirdin":w<l?"Geride kaldın":"Berabere",[["Kazandın",w],["Kaybettin",l]],B("duList","Sonuçlar"))}
/* Ben › Sezonum › Detaylar: sezondaki maçlar tek tek */
const duPl=(me,id,val,cls)=>{const p=P(id);return `<div class="dv-p ${cls||""}">${p?avatar(p):""}<b>${id===me?"Sen":esc(shortName(nameOf(id)))}</b>${val!==""&&val!=null?`<em class="num">${val}</em>`:""}</div>`};
// cevapsız teklif 1 saat sonra iptal olur: kalan süre
function duKal(d,inb){if(!d.e)return"";const dk=Math.ceil((d.e-Date.now())/6e4);if(dk<=0)return"";return inb?` Yanıt için ${dk} dk kaldı.`:` ${dk} dk içinde yanıt gelmezse iptal olur, hakkın geri gelir.`}
function duCard(m,d,me,open,soz,dolu,shr){const ot=d.a===me?d.b:d.a;const on=esc(firstName(nameOf(ot)));const r=d.s==="kabul"?duRes(m,d,me):null;const iA=d.a===me;let st,sc="",q=`“${duK(d.k)}.”`,ft="",bt="",va="",vb="",ca="",cb="";
    if(d.s==="bekliyor"&&!iA){st="Yanıt bekliyor";ft=dolu?`${on} sana meydan okudu. 3 kabul hakkın doldu.`:`${on} sana meydan okudu. Var mısın?${duKal(d,true)}`;bt=open?`<div class="dv-b"><button class="dv-no" data-act="duNo" data-v="${d.id}">Yokum</button><button class="dv-yes" data-act="duYes" data-v="${d.id}"${dolu?" disabled":""}>Varım</button></div>`:""}
    else if(d.s==="bekliyor"){st="Yanıt bekliyor";ft=`${on} henüz yanıt vermedi.${duKal(d)}`;bt=open?`<div class="dv-b one"><button class="dv-no" data-act="duCancel" data-v="${d.id}">Geri çek</button></div>`:""}
    else if(!r){st=m.state==="bitti"?duBek(d):"Maçta belli olur";ft=m.state==="bitti"?"Sonuç veri girilince belli olur.":"Söz verildi. Gerisini saha söyler."}
    else{const mx=duNum(d,r.x),ox=duNum(d,r.y);va=iA?mx:ox;vb=iA?ox:mx;const w=r.r==="G",l=r.r==="M";st=w?"Haklı çıktın":l?"Bu sefer olmadı":"Berabere";sc=w?"w":l?"l":"";
      const mine=w?"win":l?"lose":"",their=w?"lose":l?"win":"";ca=iA?mine:their;cb=iA?their:mine;
      q=`${duT(d.k)} ${w?"senin":l?"rakibinde":"ortada kaldı"}`;ft=w?`${on} çok konuştu, sen yaptın.`:l?`Bu sefer ${on} haklı çıktı.`:"Kimse haklı çıkmadı."}
    return `<div class="dv"><div class="dv-t"><span class="dv-g">Düello</span><span class="dv-s ${sc}">${st}</span></div><div class="dv-v">${duPl(me,d.a,va,ca)}<i>VS</i>${duPl(me,d.b,vb,cb)}</div><p class="dv-q">${q}</p>${ft?`<p class="dv-f">${ft}</p>`:""}${soz&&r?`<p class="dv-f">“${duK(d.k)}” ${iA?"demiştin":"demişti"}.</p>`:""}${bt}${shr&&d.s==="kabul"&&(r||m.state!=="bitti")?`<button class="dv-shr" data-act="duShare" data-v="${d.id}">${mnI("fw")}<span>Paylaş</span></button>`:""}</div>`}

/* sonuç ekranları: uygulama açılınca bir kez. Düello tek tek, oylama afiş. */
const AF_C={n8:"#3DF2A6",n7:"#8BE04E",n65:"#E3C33C",n6:"#EE8A2A",n5:"#FF7A93"};
/* Haftanın düello kralı: maçın tüm düelloları sonuçlanınca sunucu belirler. Ödül: gelecek maçta kaptanlık. Rakip kaptanı yönetici seçer. */
const duKingRec=mid=>(DU.kings||[]).find(k=>k.m===mid)||null;
function duPrevM(m){const t=matchTs(m);return S.matches.filter(x=>x.id!==m.id&&x.state==="bitti"&&!isExt(x)&&!x.archived&&matchTs(x)<t).sort((a,b)=>matchTs(b)-matchTs(a))[0]||null}
// bu maçta ödülü geçerli kral (kadroda değilse ödül yanar)
function duKingFor(m){if(!m||typeof DU==="undefined")return null;const pm=duPrevM(m);const k=pm&&duKingRec(pm.id);if(!k||!k.p||!P(k.p)||!plAll(m).includes(k.p))return null;return{k,pm,p:k.p}}
// sıralama: çok kazanan, az kaybeden, çok düello yapan
function duTally(L){const T={};const add=(id,w,l,o)=>{const x=T[id]||(T[id]={p:id,w:0,l:0,n:0,o:0});if(o){x.o++;return}x.n++;x.w+=w;x.l+=l};
  L.forEach(([m,d])=>{const r=duRes(m,d,d.a);if(!r){add(d.a,0,0,1);add(d.b,0,0,1);return}add(d.a,r.r==="G"?1:0,r.r==="M"?1:0);add(d.b,r.r==="M"?1:0,r.r==="G"?1:0)});
  return Object.values(T).filter(x=>P(x.p)).sort((a,b)=>b.w-a.w||a.l-b.l||b.n-a.n||nameOf(a.p).localeCompare(nameOf(b.p),"tr"))}
const duOf=m=>{const pl=plAll(m);return (DU.rows||[]).filter(d=>d.m===m.id&&d.s==="kabul"&&pl.includes(d.a)&&pl.includes(d.b)).map(d=>[m,d])};
function duSerit(m){if(!isMember()||S.fol||typeof DU==="undefined")return"";const pm=duPrevM(m);const k=pm&&duKingRec(pm.id);if(!k||!k.p||!P(k.p))return"";const pl=plAll(m);
  if(pl.includes(k.p)&&m.state==="takim")return duKapKart(m);const me=k.p===myPid();const fn=esc(firstName(nameOf(k.p)));
  const [t,s]=!pl.length?[me?"Düello kralı sensin":fn+" düello kralı",me?"Ödülün: bu maçta kaptan olacaksın":"Ödülü: bu maçta kaptan olacak"]:pl.includes(k.p)?[me?"Bu maçta kaptansın":fn+" bu maçta kaptan","Geçen haftanın düello kralının ödülü"]:[me?"Düello kralı sensin":fn+" düello kralı","Bu maçta kadroda değil, ödül kullanılmıyor"];
  return `<button class="ymf ymf-du1" data-act="duKralOpen" data-id="${esc(pm.id)}">${KRL_TAC}<span><b>${t}</b><small>${s}</small></span><i aria-hidden="true">›</i></button>`}
function duKapKart(m){if(!isMember()||S.fol||m.state!=="takim")return"";const K=duKingFor(m);if(!K)return"";const me=K.p===myPid();
  const t=me?"Bu maçta kaptansın":esc(firstName(nameOf(K.p)))+" bu maçta kaptan";const s="Geçen haftanın düello kralının ödülü";
  return `<div class="ymf ymf-du"><button class="ymf-m" data-act="duKralOpen" data-id="${esc(K.pm.id)}"><span class="ymf-x" aria-hidden="true">${KRL_TAC}</span><span><b>${t}</b><small>${s}</small></span></button><i aria-hidden="true">›</i></div>`}
/* Fantezi Kadro: kadro açıklanınca 5 oyuncu (1 kaleci) seçilir; puan = seçilenlerin maç notu, kaptan 2 kat. Sikke yok. */
const FZ={rows:null,n:{},who:{},at:0};
const FZ_ERR={auth:"Önce giriş yapmalısın",match:"Maç bulunamadı",closed:"Maç başladı, kadro kilitlendi",sayi:"En az 4 oyuncu seçmelisin",kaptan:"Bir kaptan seç",kadro:"Seçtiklerin bu maçın kadrosunda olmalı",takim:"Bir takımdan en çok 3 oyuncu alabilirsin",kaleci:"Kadronda 1 kaleci olmalı",butce:"Bütçeyi aştın"};
const FZ_IC='<svg viewBox="0 0 256 256" fill="#fff" aria-hidden="true"><path d="M247.59,61.22,195.83,33A8,8,0,0,0,192,32H160a8,8,0,0,0-8,8,24,24,0,0,1-48,0,8,8,0,0,0-8-8H64a8,8,0,0,0-3.84,1L8.41,61.22A15.76,15.76,0,0,0,1.82,82.48l19.27,36.81A16.37,16.37,0,0,0,35.67,128H56v80a16,16,0,0,0,16,16H184a16,16,0,0,0,16-16V128h20.34a16.37,16.37,0,0,0,14.58-8.71l19.27-36.81A15.76,15.76,0,0,0,247.59,61.22Z"/></svg>';
function fzLoad(force){if(!isMember()||S.fol||!myPid())return;if(FZ.at===-1||(!force&&Date.now()-FZ.at<60000))return;FZ.at=-1;
  rpc("fantasy_list",{}).then(r=>{FZ.at=Date.now();if(r&&r.ok){const o=JSON.stringify([FZ.rows,FZ.n]);FZ.rows=r.rows||[];FZ.n=r.n||{};FZ.who=r.who||{};FZ.cup=r.cup||null;setTimeout(fzDuyur,800);setTimeout(cupDuyur,1600);if(o!==JSON.stringify([FZ.rows,FZ.n])&&(S.tab==="mac"||S.tab==="oyun"))render(true)}}).catch(()=>{FZ.at=Date.now()-50000})}
const fzOpen=m=>!!m&&m.state==="takim"&&!m.archived&&Date.now()<matchTs(m);
const fzPool=m=>plAll(m).filter(realP);
const fzGks=m=>[lineupOf(m,"A")[0],lineupOf(m,"B")[0]].filter(Boolean);
const fzRole=(m,id)=>fzGks(m).includes(id)?"KL":(roleIn(m,id,sideOf(m,id))||"OS");
const fzPr=id=>Math.round(mvOf(id)*10)/10;
// bütçe: bu maçın oyuncularının ortalama değeri x 5 — ortalama bir kadro tam sığar, yıldız alan başka yerden kısar
function fzBudget(m){const L=fzPool(m).map(fzPr).filter(v=>v>0);return L.length?Math.round(5*L.reduce((a,b)=>a+b,0)/L.length):0}
const fzMine=m=>(FZ.rows||[]).find(r=>r.m===m.id&&r.p===myPid())||null;
// puan: yalnızca maç kaydındaki veri (skor, gol, asist, saha verisi); oy ve maç notu sayılmaz
// puan değerleri her maç için o maçtan önceki bütün maçlardan hesaplanır: bir mevkide gol/asist ne kadar seyrekse o kadar değerli
const FZ_R=["KL","DF","OS","FV"];const FZC={};
function fzRates(m){const F=fin().filter(x=>!isExt(x)&&x.id!==m.id&&matchTs(x)<matchTs(m)&&x.score_a!=null);const key=m.id+":"+F.map(x=>x.id).join(",");if(FZC[m.id]&&FZC[m.id].k===key)return FZC[m.id].v;
  const ap={},g={},a={},km={},tk={},pa={};let conc=0,cn=0,tg=0,ta=0,tn=0;
  F.forEach(x=>{for(const sd of["A","B"]){const L=lineupOf(x,sd).length?lineupOf(x,sd):(sd==="A"?x.team_a:x.team_b)||[];L.forEach(id=>{if(!realP(id))return;const r=fzRole(x,id);const o=(x.stats||{})[id]||{};
      ap[r]=(ap[r]||0)+1;g[r]=(g[r]||0)+(+o.g||0);a[r]=(a[r]||0)+(+o.a||0);tg+=+o.g||0;ta+=+o.a||0;tn++;const t=trkOf(x,id);if(t){if(isFinite(+t.km))(km[r]=km[r]||[]).push(+t.km);if(isFinite(+t.tk))(tk[r]=tk[r]||[]).push(+t.tk);if(isFinite(+t.pa))(pa[r]=pa[r]||[]).push(+t.pa)}});
    conc+=sd==="A"?+x.score_b:+x.score_a;cn++}});
  const W=5,gA=tn?tg/tn:1,aA=tn?ta/tn:.9;const cl=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));const av=L=>L&&L.length?L.reduce((x,y)=>x+y,0)/L.length:null;
  const v={n:F.length,gol:{},ast:{},km:{},tk:{},pa:{},yen:cn?Math.round(conc/cn*10)/10:6,ortG:{},ortA:{}};
  FZ_R.forEach(r=>{const n=ap[r]||0;const og=((g[r]||0)+W*gA)/(n+W),oa=((a[r]||0)+W*aA)/(n+W);v.ortG[r]=n?(g[r]||0)/n:null;v.ortA[r]=n?(a[r]||0)/n:null;
    v.gol[r]=F.length?cl(Math.round(6/Math.max(og,.01)),2,8):{FV:4,OS:5,DF:6,KL:8}[r];v.ast[r]=F.length?cl(Math.round(3/Math.max(oa,.01)),1,4):3;if(r==="KL"){v.gol.KL=10;v.ast.KL=8}if(r==="DF")v.ast.DF=6;const k=av(km[r]),t=av(tk[r]);if(k!=null)v.km[r]=Math.round(k*10)/10;if(t!=null)v.tk[r]=Math.round(t);const q=av(pa[r]);if(q!=null)v.pa[r]=Math.round(q)});
  FZC[m.id]={k:key,v};return v}
const fzReady=m=>!!m&&mDone(m)&&m.score_a!=null&&m.score_b!=null;
function fzRaw(m,id){if(!fzReady(m)||!plAll(m).includes(id)||!realP(id))return null;const sd=sideOf(m,id);if(!sd)return null;const rl=fzRole(m,id);const o=(m.stats||{})[id]||{};const R=fzRates(m);
  const my=sd==="A"?+m.score_a:+m.score_b,op=sd==="A"?+m.score_b:+m.score_a;const L=[["Oynadı",1]];const g=+o.g||0,a=+o.a||0,og=+o.og||0;
  if(g)L.push([g+" gol",g*R.gol[rl]]);if(a)L.push([a+" asist",a*R.ast[rl]]);if(my>op)L.push(["Galibiyet",2]);else if(my===op)L.push(["Beraberlik",1]);
  if(rl==="KL"||rl==="DF"){if(op<R.yen)L.push(["Ortalamadan az gol yedi",rl==="KL"?3:2]);if(rl==="KL"&&op<=R.yen-3)L.push(["Çok az gol yedi",2]);if(rl==="KL"&&op>=R.yen+3)L.push(["Çok gol yedi",-Math.floor((op-R.yen)/3)])}
  if(og)L.push(["Kendi kalesine",-2*og]);const ps=+o.ps||0,cl=+o.cl||0,pm=+o.pm||0,pn=+o.pen||0;if(ps)L.push([ps+" penaltı kurtardı",5*ps]);if(cl)L.push([cl+" kez çizgiden çıkardı",3*cl]);if(pm)L.push([pm+" penaltı kaçırdı",-2*pm]);if(pn)L.push([pn+" penaltı yaptırdı",-1*pn]);const t=trkOf(m,id);if(t){if(R.km[rl]!=null&&+t.km>R.km[rl])L.push(["Mevki ortalamasından çok koştu",1]);if(R.tk[rl]!=null&&+t.tk>R.tk[rl])L.push(["Mevki ortalamasından çok top kaptı",1]);if((rl==="DF"||rl==="OS")&&R.pa[rl]!=null&&+t.pa>R.pa[rl])L.push(["Mevki ortalamasından çok pas arası",1])}
  return{pts:L.reduce((x,y)=>x+y[1],0),L,rl}}
// mevki dengesi (26 Kasım 2026 sonrası maçlar): her mevkinin önceki maçlardaki ortalaması takım ortalamasına eşitlenir; eski maçların puanı değişmez
const FZ_DENGE=new Date(2026,10,26).getTime(),FZD={};
function fzDenge(m){const F=fin().filter(x=>!isExt(x)&&x.id!==m.id&&matchTs(x)<matchTs(m)&&fzReady(x));const key=F.map(x=>x.id).join(",");if(FZD[m.id]&&FZD[m.id].k===key)return FZD[m.id].v;
  const rs={};let t=0,n=0;F.forEach(x=>plAll(x).forEach(id=>{const r=fzRaw(x,id);if(!r)return;(rs[r.rl]=rs[r.rl]||[0,0]);rs[r.rl][0]+=r.pts;rs[r.rl][1]++;t+=r.pts;n++}));
  const a=n?t/n:8,W=3,v={};FZ_R.forEach(r=>{const x=rs[r]||[0,0];v[r]=clamp(a/Math.max(1,(x[0]+W*a)/(x[1]+W)),.6,2.5)});FZD[m.id]={k:key,v};return v}
function fzScore(m,id){const r=fzRaw(m,id);if(!r||matchTs(m)<FZ_DENGE)return r;const f=fzDenge(m)[r.rl]||1,d=Math.round(r.pts*f)-r.pts;if(d){r.L.push(["Mevki dengesi",d]);r.pts+=d}return r}
const fzSc=(m,id)=>{const r=fzScore(m,id);return r?r.pts:null};
function fzPts(m,r){if(!fzReady(m)||!r)return null;let s=0;(r.picks||[]).forEach(id=>{const v=fzSc(m,id);if(v!=null)s+=v*(id===r.cap?2:1)});return s}
function fzAvg(id){const y=curYr();let n=0,s=0;fin().forEach(m=>{if(yrOf(m)!==y)return;const v=fzSc(m,id);if(v!=null){n++;s+=v}});return n?s/n:null}
function fzWeek(m){if(!fzReady(m))return[];return (FZ.rows||[]).filter(r=>r.m===m.id&&P(r.p)).map(r=>({...r,pts:fzPts(m,r)})).filter(r=>r.pts!=null).sort((a,b)=>b.pts-a.pts||(fzSc(m,b.cap)||0)-(fzSc(m,a.cap)||0)||nameOf(a.p).localeCompare(nameOf(b.p),"tr"))}
function fzSeason(){const y=curYr();const T={};fin().filter(m=>yrOf(m)===y&&!isExt(m)).forEach(m=>fzWeek(m).forEach(r=>{const x=T[r.p]||(T[r.p]={p:r.p,pts:0,n:0,best:0});x.pts+=r.pts;x.n++;x.best=Math.max(x.best,r.pts)}));
  return Object.values(T).sort((a,b)=>b.pts-a.pts||b.best-a.best)}
const fzRk=(L,p)=>{const i=L.findIndex(r=>r.p===p);return i<0?"–":(i+1)+"."};
const FZ_ZOR=["KL","DF","OS","FV"];const FZ_AD={KL:"kaleci",DF:"defans",OS:"orta saha",FV:"forvet",SB:"serbest"};
