function cupWeeks(){const c=FZ.cup;if(!c)return[];const L=S.matches.filter(m=>!isExt(m)).sort((a,b)=>matchTs(a)-matchTs(b));const i=L.findIndex(m=>m.id===c.start);return i<0?[]:L.slice(i,i+4)}
