    if(!sz&&!L.length){const n=FZ.n[m.id]||0;return hd+seg+`<div class="fz-bos"><b>${n} kişi kadro kurdu</b><span>${open||!fzReady(m)?"Kadrolar ve puanlar maçtan sonra burada":"Bu maçta kadro kuran olmadı"}</span></div>`+ft}
