/* rozet koleksiyonu */
function fzRozet(pid){const W=fin().filter(m=>!isExt(m)&&fzReady(m)).sort((a,b)=>matchTs(a)-matchTs(b)).map(m=>({m,L:fzWeek(m)})).filter(x=>x.L.length);
  let men=0,pod=0,st=0,mx=0,cap=false,deg=false,c50=false;W.forEach(({m,L})=>{const i=L.findIndex(r=>r.p===pid);if(i===0)men++;if(i>=0&&i<3)pod++;if(i>=0){st++;mx=Math.max(mx,st)}else st=0;if(i<0)return;const r=L[i];const sc=id=>fzSc(m,id)||0;
    const top=Math.max(...fzPool(m).map(sc));if(sc(r.cap)>0&&sc(r.cap)===top)cap=true;const pr=r.prices||[];if(pr.length===r.picks.length){const lo=Math.min(...pr),k=pr.indexOf(lo);if(lo<Math.max(...pr)&&r.picks.every((id,j)=>j===k||sc(id)<sc(r.picks[k])))deg=true}if(r.pts>=50)c50=true});
  const B=(on,t,d,off)=>({e:"",t,d:on?d:off,on:!!on});
  return[B(men,"Haftanın Menajeri",men+" kez haftanın menajeri","Fantezi'de haftanın birincisi ol"),B(pod>=3,"Podyum",pod+" kez ilk üçte bitirdi",pod+" / 3 kez ilk üç"),B(mx>=5,"Müdavim","5 hafta üst üste kadro kurdu",Math.min(st,5)+" / 5 hafta üst üste kadro"),
    B(cap,"Doğru Kaptan","Kaptanı haftanın en çok puan alanı oldu","Kaptanın haftanın en iyisi olsun"),B(deg,"Değer Avcısı","En ucuz oyuncusu kadronun yıldızı oldu","Kadronun en ucuzu en çok puanı alsın"),B(c50,"50 Puan Kulübü","Bir haftada 50+ puan topladı","Bir haftada 50 puanı geç")].concat(cupRozet(pid))}
function rztList(pid){const L=((S.stats[pid]||{}).rzt||[]).slice();
  const kn=(DU.kings||[]).filter(k=>k.p===pid).length;L.push({e:"⚔️",t:"Düello Kralı",d:kn?kn+" kez haftanın düello kralı":"Haftanın düello kralı ol",on:!!kn});
  if(!tahminYok()&&BET.feed){const C=BET.feed.rows.filter(c=>c.p===pid&&c.z!=="acik").sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));let st=0,mx=0;for(const c of C){if(c.z==="kazandi"){st++;mx=Math.max(mx,st)}else if(c.z==="kaybetti")st=0}
    const H=(BET.kral&&BET.kral.hist||[]).filter(x=>x.p===pid).length;const T=(on,e,t,d,off)=>L.push({e,t,d:on?d:off,on:!!on,bet:true});
    T(C.some(c=>c.z==="kazandi"&&c.odd>=5),"🎯","Sürpriz Avcısı","5,00 üstü oranı tutturdu","5,00 üstü bir oranı tuttur");
    T(mx>=3,"🔥","Seri Tahminci",mx+" tahmin üst üste tuttu",mx+" / 3 üst üste tahmin");
    T(C.some(c=>c.z==="kazandi"&&(c.legs||[]).length>=3),"🧩","Kombine Ustası","3'lü kombineyi tutturdu","3'lü bir kombine tuttur");
    T(H,"👑","Tahmin Kralı",H+" kez haftanın tahmin kralı","Haftanın tahmin kralı ol")}
  if(isMember()&&!S.fol&&myPid()){fzLoad();if(FZ.at>0)fzRozet(pid).forEach(b=>L.push(Object.assign(b,{bet:true})))}
  const sh=L.filter(b=>b.shame);return L.filter(b=>b.on&&!b.shame).concat(L.filter(b=>!b.on),sh)}
