  x.textAlign="left";x.fillStyle="#fff";const sT=`${nmOf(m,"A")} ${sa}–${sb} ${nmOf(m,"B")}`;fitFont(x,sT,56,30,900,SD,W-120);x.fillText(sT,60,280);
  const ims=await Promise.all(ids.map(id=>loadImg(photoOf(id))));
