  let E=T.filter(c=>ultRoles(c.pid)[0]===r);if(E.length<3)E=E.concat(T.filter(c=>!E.includes(c)&&ultRoles(c.pid).includes(r)));if(E.length<2)E=E.concat(T.filter(c=>!E.includes(c)).slice(0,2-E.length));
