// Takım ekranındaki sahanın aynısı: aynı kartlar, aynı kimya çizgileri. onz: sıradaki yere önizlenen kart
function ultDrSaha(pick,sira,onz){const P2=pick.slice();if(onz&&sira>=0)P2[sira]=onz;const x=ultLine(ultDrL(P2)),lines=[];
  for(let i=0;i<7;i++)for(let j=i+1;j<7;j++){if(!x.cs[i]||!x.cs[j])continue;const v=ultBag(x.cs[i].pid,x.cs[j].pid);if(!v)continue;const[,x1,y1]=x.sl[i],[,x2,y2]=x.sl[j],mx=(x1+x2)/2+(y2-y1)*.18,my=(y1+y2)/2-(x2-x1)*.18;
    let ust=0;for(let t=.08;t<.93&&!ust;t+=.04){const px=(1-t)*(1-t)*x1+2*(1-t)*t*mx+t*t*x2,py=(1-t)*(1-t)*y1+2*(1-t)*t*my+t*t*y2;ust=x.sl.some(([,cx,cy],q)=>q!==i&&q!==j&&x.cs[q]&&Math.abs(px-cx)<11&&Math.abs(py-cy)<12)}
    lines.push(`<path d="M${x1} ${y1} Q${mx} ${my} ${x2} ${y2}" fill="none" stroke="${v>1?"#F5C542":"#00E58A"}" stroke-width="${v>1?1.6:.9}" opacity="${ust?.3:.9}"${ust?' stroke-dasharray="2 1.5"':""} stroke-linecap="round"/>`)}
  const slots=x.sl.map(([r,lx,ly,fp],i)=>{const c=x.cs[i],on=i===sira;if(!c)return `<div class="ulp-s ulq bos${on?" sel":""}" style="left:${lx}%;top:${ly}%"><span class="ulq-e" aria-label="${fp||r}${on?", sıradaki yer":""}">+<small>${fp||r}</small></span></div>`;
    const md=!ultRoles(c.pid).includes(r)&&c.y!=="joker",tam=!md&&ultTam(c.pid,x.sl[i]);
    return `<div class="ulp-s ulq ulqk${on?" sel onz":""}" style="left:${lx}%;top:${ly}%"><div class="ulqk-c">${ultCardH(c,{sm:1})}</div><span class="ulqk-a"><span class="ulq-p${md?" md":tam?" ok":""}">${md?"Mevki dışı":(tam?"✓ ":"")+esc(fp||r)}</span><span class="ulq-k" aria-hidden="true">${[0,1,2].map(k=>`<i class="${k<(md?0:x.ch[i])?"on":""}"></i>`).join("")}</span></span></div>`}).join("");
  return{x,h:`<div class="ulp ulkom ulq-saha kv2 uldr-saha"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><g stroke="rgba(255,255,255,.16)" stroke-width=".5" fill="none"><rect x="2" y="2" width="96" height="96" rx="2"/><line x1="2" y1="50" x2="98" y2="50"/><circle cx="50" cy="50" r="10"/></g>${lines.join("")}</svg>${slots}</div>`}}
function ultDrOdH(g){return `<div class="uldr-od">${ULT_DR_OD.map((o,i)=>`<div class="${g===i?"on":""}"><b class="num">${i}</b><small>${o.join("<br>")}</small></div>`).join("")}</div>`}
function ultDrTab(){ultDrYukle();const st=ultSt(),d=ultDr(),B=ultBuild();const bas=`<div class="ulsec-h"><h3>${d?(d.pick.length<7?`Kadro Kur · ${d.pick.length+1} / 7`:d.ms.length<4?`Draft Kadron · ${d.ms.length} / 4 Maç`:"Draft Bitti"):"Bu Haftanın Draft'ı"}</h3><button class="ulbas-i" data-act="ultBilgi" data-v="draft" aria-label="Draft nasıl çalışır"><span>i</span></button></div>`;
  if(!(st.kulup||[]).length)return `<section class="card ulsec">${bas}<p class="ult-n">Önce hoş geldin paketini aç: Kulüp › Bugün.</p></section>`;
  if(!d)return `<section class="card ulsec uldr">${bas}<p class="uldr-a">Kendi kulübün sayılmaz. Her mevki için kura ile 3 kart gelir, birini seçersin; kurduğun kadroyla 4 maç oynarsın. Haftada 1 hak.</p><button class="btn primary ult-w" data-act="ultDrBasla">Draft'a Başla</button></section><section class="card ulsec"><div class="ulsec-h"><h3>Ödüller</h3><small class="ulplan-s">4 maç</small></div>${ultDrOdH(-1)}</section>`;
  if(d.pick.length<7){const i=d.pick.length,r=ultSL(ULT_DR_F)[i][0],O=ultDrSec(ultDrTohum(),i,d.pick);if(!O.includes(ULT.drS))ULT.drS=O[0];
    const x0=ultLine(ultDrL(d.pick)),SH=ultDrSaha(d.pick,i,ULT.drS),sc=B.C.find(c=>c.id===ULT.drS);
    const dl=(v,t,dec)=>`<i class="${v>0?"p":v<0?"n":"z"}">${t} ${v>0?"+":v<0?"−":"±"}${dec?fN(Math.abs(v)):Math.abs(v)}</i>`;
    const ops=O.map(id=>{const c=B.C.find(q=>q.id===id),P2=d.pick.concat([id]),x=ultLine(ultDrL(P2)),tam=ultTam(c.pid,x.sl[i]),md=!ultRoles(c.pid).includes(r)&&c.y!=="joker";
      return `<div class="ultc${id===ULT.drS?" best":""}" data-act="ultDrSec" data-v="${esc(id)}"><span class="ultc-k">${ultCardH(c,{sm:1,act:"ultDrSec"})}</span><span class="ulyd-d">${md?`<i class="n">Mevki dışı</i>`:""}${dl(x.chem-x0.chem,"Kimya")}${i?dl(Math.round((x.str-x0.str)*10)/10,"Güç",1):`<i class="z">Güç ${c.r}</i>`}</span></div>`}).join("");
    return `<section class="uldr uldr-sec"><h3 class="uldr-gz">Kadro Kur · ${i+1} / 7</h3><div class="uldr-st uldr-sb">${[0,1,2,3,4,5,6].map(j=>`<i class="${j<i?"d":j===i?"n":""}"></i>`).join("")}<button class="ulbas-i" data-act="ultBilgi" data-v="draft" aria-label="Draft nasıl çalışır"><span>i</span></button></div>
      <div class="uldr-2"><div class="uldr-l">${SH.h}</div>
      <div class="uldr-r"><section class="card ultep uldr-t"><div class="ultx uldr-th"><p class="ultx-h"><b>${i+1} / 7 · ${ULT_DR_AD[r]} Seç</b><span>Güç ${SH.x.n?fN(SH.x.str):"–"} · Kimya ${SH.x.chem}</span></p>${sc?`<button class="uldr-dv" data-act="ultDrAl" aria-label="${esc(shortName(nameOf(sc.pid)))} ile devam et">Devam Et</button>`:""}</div><div class="ultc-l uldr-ol">${ops}</div></section></div></div></section>`}
  const x=ultLine(ultDrL(d.pick)),g=d.ms.filter(m=>m.ga>m.gb).length,bit=d.ms.length>=4,nx=bit?null:ultDrRakip(d.ms.length);
  return `<section class="uldr"><div class="ulsec-h uldr-h"><h3>${d.ms.length<4?`Draft Kadron · ${d.ms.length} / 4 Maç`:"Draft Bitti"}</h3><button class="ulbas-i" data-act="ultBilgi" data-v="draft" aria-label="Draft nasıl çalışır"><span>i</span></button></div>${ultDrSaha(d.pick,-1).h}</section><section class="card ulsec uldr"><p class="uldr-g"><span><b class="num">${fN(x.str)}</b>Güç</span><span><b class="num">${x.chem}</b>Kimya</span><em>${g} galibiyet</em></p>
    <div class="uldr-m">${[0,1,2,3].map(j=>{const m=d.ms[j];return m?`<span class="${m.ga>m.gb?"w":m.ga<m.gb?"l":"d"}"><b class="num">${m.ga}-${m.gb}</b><small>${esc(String(m.ad).replace(" Kadrosu",""))}</small></span>`:`<span class="${j===d.ms.length?"nx":""}"><b>${j+1}. Maç</b><small>${j===d.ms.length&&nx?esc(String(nx.ad).replace(" Kadrosu","")):"–"}</small></span>`}).join("")}</div>
    ${bit?`<p class="uldr-a"><b>${g} galibiyet · ${ULT_DR_OD[g].join(" ve ")}</b>Yeni Draft pazartesi açılır.</p>`:`<button class="btn primary ult-w" data-act="ultDrOyna">${d.ms.length+1}. Maçı Oyna · ${esc(nx.ad)}</button><p class="ulgh-s">Rakip, bu hafta Draft kurmuş bir oyuncunun kadrosudur; henüz kuran yoksa kura kadrosu. Beraberlik galibiyet sayılmaz. Kadron kilitli, sonuçlar sunucuya kaydedilir.</p>`}</section>
    <section class="card ulsec"><div class="ulsec-h"><h3>Ödüller</h3><small class="ulplan-s">4 maç</small></div>${ultDrOdH(bit?g:-1)}</section>`}
// ---------- özel maçlar: Maçın Rövanşı (rv|<maç>) ve Süper Kupa (sk|<sezon>). İlk hesaplanan sonuç sunucuda saklanır; herkes aynı maçı izler ----------
const ULT_OZ={at:0,yk:0,ok:0,m:{},k:""},ULT_RV_BAS="2026-11-23";
async function ultOzYukle(f){if(!ULT_SRV.ok||!S.session||ULT_OZ.yk)return;if(!f&&ULT_OZ.at&&Date.now()-ULT_OZ.at<120000)return;ULT_OZ.yk=1;
  try{const r=await rpc("ult_ozel",{});ULT_OZ.at=Date.now();if(r&&r.ok){const m={};for(const x of r.l||[])m[x.k]={...x.p,at:x.at};const k=Object.keys(m).sort().join();ULT_OZ.m=m;ULT_OZ.ok=1;if(k!==ULT_OZ.k){ULT_OZ.k=k;render(true)}ultRvKur();ultSkOto();ultOzOdul()}}catch(_){}ULT_OZ.yk=0}
async function ultOzYaz(k,pay){const r=await rpc("ult_ozel_yaz",{p_k:k,p_payload:pay}).catch(()=>null);if(r&&r.ok&&r.p){ULT_OZ.m[k]={...r.p,at:r.at};ULT_OZ.k=Object.keys(ULT_OZ.m).sort().join();return ULT_OZ.m[k]}return null}
const ultRvAd=(m,s)=>cleanName((m||{})["name_"+s.toLowerCase()]||"")||(s==="A"?"A Takımı":"B Takımı");
const ultRvMaclar=()=>ultBuild().F.filter(m=>String(m.date)>=ULT_RV_BAS&&plOf(m,"A").length&&plOf(m,"B").length);
// o günkü kadro: herkes o maçta oynadığı mevkide, maç sonrası reytingiyle; diziliş mevkilere en uygun olan
function ultRvSnap(m,side){const pts=(S.mInfo[m.id]||{}).pts||{},ids=plOf(m,side).filter(id=>P(id)&&!P(id).guest).slice(0,7);
  const rl=id=>(pts[id]&&pts[id].role)||ultRoles(id)[0]||"OS",rt=id=>{const h=((S.stats[id]||{}).hist||[]).find(h=>h&&h.m&&h.m.id===m.id);return Math.floor(+(h&&(h.gx??h.ovr))||+ovrOf(id)||70)};
  const have={};ids.forEach(id=>have[rl(id)]=(have[rl(id)]||0)+1);let f="2-2-2",bs=-1;for(const k of Object.keys(ULT_F)){const need={KL:1};ULT_F[k].forEach(r=>need[r]=(need[r]||0)+1);let sc=0;for(const r in need)sc+=Math.min(need[r],have[r]||0);if(sc>bs){bs=sc;f=k}}
  const SL=ultSL(f),c=[null,null,null,null,null,null,null],kal=ids.slice();SL.forEach(([r],i)=>{const j=kal.findIndex(id=>rl(id)===r);if(j>=0)c[i]=kal.splice(j,1)[0]});for(let i=0;i<7;i++)if(!c[i]&&kal.length)c[i]=kal.shift();
  return ultSnapA({f,t:"dengeli",c:c.map(id=>id?{id:"rv-"+id+"-"+m.id,pid:id,r:rt(id),type:"temel"}:null)})}
async function ultRvKur(){if(ULT.rvB||!ULT_OZ.ok)return;ULT.rvB=1;try{for(const m of ultRvMaclar().slice(-2)){const k="rv|"+m.id;if(ULT_OZ.m[k])continue;const d=parseYmd(m.date);if(!(m.vote_closed_at||d&&Date.now()>d.getTime()+2*864e5))continue;
    const ka=ultRvSnap(m,"A"),kb=ultRvSnap(m,"B");if(ka.c.filter(Boolean).length<5||kb.c.filter(Boolean).length<5)continue;const R0=ultResult(ultPlan(ultFromSnap(ka),ultFromSnap(kb),TID+k));if(await ultOzYaz(k,{ga:R0.ga,gb:R0.gb,ka,kb,v:ULT_MV}))render(true)}}catch(_){}ULT.rvB=0}
function ultOzIzle(k){const p=ULT_OZ.m[k];if(!p)return;const st=ultSt(),me=myPid();st.ozG=st.ozG||[];const tekrar=st.ozG.includes(k);if(!tekrar){st.ozG=st.ozG.concat([k]).slice(-40);ultSave()}
  if(!p.ka||!p.kb){toast(`Tekrar izleme kapandı · sonuç ${p.ga} – ${p.gb}`);ultOzOdul();render(true);return}if((p.v||1)>ULT_MV){ultGuncelle();return}
  const rv=k.startsWith("rv|");let un,on,flip=false,izle;if(rv){const m=S.matches.find(x=>x.id===k.slice(3));un=ultRvAd(m,"A");on=ultRvAd(m,"B");izle=(p.ka.c.find(Boolean)||{}).pid}else{flip=p.aw===me;un=p.h===me||flip?"Sen":shortName(nameOf(p.h));on=shortName(nameOf(flip?p.h:p.aw));izle=p.h===me||flip?null:p.h}
  const LA0=ultFromSnap(p.ka),LB0=ultFromSnap(p.kb);if(p.kr&&p.kr.a)LA0.kr=p.kr.a;if(p.kr&&p.kr.b)LB0.kr=p.kr.b;
  let P0=ultPlan(LA0,LB0,TID+k,p.v||1);if(flip)P0=ultFlip(P0);let R0=ultResult(P0);const sa=flip?+p.gb:+p.ga,sb=flip?+p.ga:+p.gb;let uy=0;if(R0.ga!==sa||R0.gb!==sb){uy=1;R0={...R0,ga:sa,gb:sb,gl:[]}}
  let rs=sa>sb?(un==="Sen"?"Kazandın":un+" kazandı"):sa<sb?(un==="Sen"?"Kaybettin":on+" kazandı"):"Berabere";
  if(!rv){const wn=shortName(nameOf(p.w));rs=p.pa!=null?`${p.w===me?"Penaltılarla kazandın":wn+" penaltılarla kazandı"} · ${flip?p.pb+"-"+p.pa:p.pa+"-"+p.pb}`:p.w===me?"Süper Kupa senin":wn+" Süper Kupa'yı kazandı"}
  ULT.run={kind:rv?"rv":"sk",k,opp:rv?null:(flip?p.h:p.aw),izle,un,on,rs,uy,onem:tekrar?1:undefined,skip:uy?true:undefined,P0,R0,i:0,sk:{a:0,b:0},hiz:1,feed:[],stl:{sa:0,sb:0,ka:0,ka2:0,kb2:0,fa:0,fb:0},dk:0,done:false};S.sheet={type:"ult",v:"mac"};ultOzOdul();render(true);setTimeout(ultTick,500)}
// rövanşı kazanan takımın oyuncularına +1 şans (haftalık tavana dahil); Süper Kupa şampiyonuna paket ve rozet, duvara kayıt
function ultOzOdul(){const st=ultSt(),me=myPid();let deg=0;st.rvS=st.rvS||{};const G=st.ozG||[],M=ultRvMaclar(),son=M[M.length-1];
  for(const m of M){const k="rv|"+m.id,p=ULT_OZ.m[k];if(!p||st.rvS[m.id])continue;if(!(G.includes(k)||!son||m.id!==son.id))continue;st.rvS[m.id]=1;deg=1;const w=+p.ga>+p.gb?"A":+p.ga<+p.gb?"B":null;
    if(w&&plOf(m,w).includes(me)){const d=parseYmd(m.date),v=ultSansEkle(1,isoWeek(d&&!isNaN(d)?d:new Date(ultNow())));toast(v?"Rövanşı takımın kazandı · +1 şans puanı":"Rövanşı takımın kazandı · o haftanın şans tavanı dolu")}}
  for(const k of Object.keys(ULT_OZ.m)){if(!k.startsWith("sk|"))continue;const p=ULT_OZ.m[k],sz=k.slice(3);if(!p.w)continue;ultOnYaz(k,p.w,{sz:+sz||sz});st.skOd=st.skOd||{};
    if(p.w===me&&!st.skOd[sz]){st.skOd[sz]=1;st.skN=(st.skN||0)+1;(st.mkPk=st.mkPk||[]).push({k:"sk"+sz,why:"Süper Kupa şampiyonu"});deg=1;toast("Süper Kupa senin · paketin Kulüp › Bugün'de")}}
  if(deg)ultSave()}
function ultRvH(){ultOzYukle();const M=ultRvMaclar();if(!M.length)return"";const st=ultSt(),G=st.ozG||[],m=M[M.length-1],k="rv|"+m.id,p=ULT_OZ.m[k],gor=p&&G.includes(k);
  const tk=(s)=>{const ids=plOf(m,s).filter(id=>P(id)&&!P(id).guest);return `<div><b>${esc(ultRvAd(m,s))}</b><small>Sahada ${s==="A"?+m.score_a||0:+m.score_b||0}</small><span class="ulrv-av">${ids.slice(0,4).map(id=>avatar(P(id),"sm")).join("")}${ids.length>4?`<i>+${ids.length-4}</i>`:""}</span></div>`};
  const es=M.slice(0,-1).reverse().map(x=>[x,ULT_OZ.m["rv|"+x.id]]).filter(x=>x[1]).slice(0,4);
  return `<section class="card ulsec ulrv"><div class="ulsec-h"><h3>Maçın Rövanşı</h3><button class="ulbas-i" data-act="ultBilgi" data-v="rovans" aria-label="Maçın Rövanşı nasıl çalışır"><span>i</span></button></div>
    <div class="ulrv-vs">${tk("A")}<div class="ulrv-sk"><b class="num">${gor?p.ga+" – "+p.gb:"?"}</b><small>${fmtShort(m.date)}</small></div>${tk("B")}</div>
    ${p?`<button class="btn ${gor?"":"primary "}ult-w" data-act="ultOzIzle" data-v="${esc(k)}">${gor?"Tekrar İzle":"Rövanşı İzle"}</button>`:`<p class="ult-n">${ULT_OZ.ok?"Oylama kapanınca rövanş kendiliğinden oynanır.":"Yükleniyor…"}</p>`}
    ${es.length?`<div class="ulrv-g">${es.map(([x,q])=>`<button data-act="ultOzIzle" data-v="rv|${esc(x.id)}"><span>${fmtShort(x.date)} · sahada ${+x.score_a||0}-${+x.score_b||0}</span><b class="num">Rövanş ${q.ga}-${q.gb}</b></button>`).join("")}</div>`:""}
    <p class="ulgh-s">Herkes aynı maçı izler. Rövanşı kazanan takımın oyuncuları +1 şans puanı alır.</p></section>`}
// Süper Kupa: biten sezonun lig şampiyonu ile son kupasının şampiyonu (aynı kişiyse lig ikincisi); yeni sezonun ilk maçından sonra açılır
function ultSk(){ultOnYukle();const B=ultBuild();if(B.sz.length<2)return null;const sz=B.sz[B.sz.length-2],o=ultOnSz(sz);if(!o.lig.length)return null;const lg=o.lig[o.lig.length-1],a=lg.p;
  const kp=o.kp.slice().sort((x,y)=>String(x.at||"").localeCompare(String(y.at||""))).pop();let b=kp?kp.p:null;if(!b||b===a)b=(lg.b||{}).iki||null;if(!b||b===a||!P(b))return null;
  const d1=(B.F.find(m=>String(m.season)===String(B.cur))||{}).date,d=d1&&parseYmd(d1),t0=d&&!isNaN(d)?d.getTime():0;if(!t0)return null;const k="sk|"+sz;return{sz,k,a,b,t0,p:ULT_OZ.m[k]||null}}
async function ultSkOyna(oto){const s=ultSk();if(!s||s.p||ULT.skB||!ULT_OZ.ok)return;if(ultSkT0(s)){if(!oto)ultCmYon("sk",s.k);return}const me=myPid();if(!oto&&me!==s.a&&me!==s.b)return;ULT.skB=1;
  try{if(!oto){const err=ultOk(ultMy());if(err){toast(err);return}clearTimeout(ULT_SRV.t);await ultPush()}
    const h=oto?s.a:me,aw=h===s.a?s.b:s.a,L=pid=>pid===me?ultMy():ultRakipKadro(pid),ka=ultSnap(L(h)),kb=ultSnap(L(aw));
    const R0=ultResult(ultPlan(ultFromSnap(ka),ultFromSnap(kb),TID+s.k)),pay={h,aw,ga:R0.ga,gb:R0.gb,ka,kb,v:ULT_MV};if(oto)pay.oto=1;let w=R0.ga>R0.gb?h:R0.ga<R0.gb?aw:null;if(!w){const pn=ultPenSeri(s.k,{p:pay},h);pay.pa=pn.a;pay.pb=pn.b;w=pn.a>pn.b?h:aw}pay.w=w;
    const r=await ultOzYaz(s.k,pay);if(!r){if(!oto)toast("Maç kaydedilemedi, tekrar dene");return}ultOzOdul();if(!oto)ultOzIzle(s.k);else render(true)}catch(_){}finally{ULT.skB=0}}
function ultSkOto(){const s=ultSk();if(s&&!s.p&&!ultSkT0(s)&&ultNow()>s.t0+3*864e5)ultSkOyna(true)}
function ultSkH(){ultOzYukle();const s=ultSk();if(!s)return"";const me=myPid(),p=s.p,G=ultSt().ozG||[],gor=p&&G.includes(s.k),ben=me===s.a||me===s.b;if(p&&gor&&Date.parse(p.at)<ultNow()-14*864e5)return"";
  const nm=id=>esc(shortName(nameOf(id))),son=new Date(s.t0+3*864e5-1).toLocaleDateString("tr-TR",{day:"numeric",month:"long",weekday:"long"});
  return `<section class="card ulsec ulsk"><div class="ulsec-h"><h3>Süper Kupa</h3><small class="ulplan-s">${esc(szL(s.sz))}</small></div>
    <div class="ulsk-k"><div><b>${nm(s.a)}</b><small>Lig şampiyonu</small></div><em class="num">${gor?(p.h===s.a?p.ga+" – "+p.gb:p.gb+" – "+p.ga):"VS"}</em><div><b>${nm(s.b)}</b><small>${ultOnSz(s.sz).kp.some(x=>x.p===s.b)?"Kupa şampiyonu":"Lig ikincisi"}</small></div></div>
    ${gor?`<p class="ulsk-w">🏆 ${nm(p.w)}${p.pa!=null?" · penaltılarla":""}</p>`:""}
    ${p?`<button class="btn ${gor?"":"primary "}ult-w" data-act="ultOzIzle" data-v="${esc(s.k)}">${gor?"Tekrar İzle":"Maçı İzle"}</button>`:ultSkT0(s)?(ultSkKur(),ultCmKart("sk",s.k,!ben)+`<p class="ulgh-s">Tek maç; berabere biterse penaltılar. Lig maçlarından 15 dakika önce başlar${ben?"; saatinde gelirsen devre arasında ve 70. dakikada kararları canlı verirsin":""}.</p>`):ben?`<button class="btn primary ult-w" data-act="ultSkOyna">Kadromla Oyna</button><p class="ulgh-s">Tek maç; berabere biterse penaltılar. Sen şu anki kadronla, rakibin kayıtlı kadrosuyla oynar. ${son} gününe kadar oynanmazsa kayıtlı kadrolarla kendiliğinden oynanır.</p>`:`<p class="ult-n">İki şampiyondan biri maçı başlatınca herkes izleyebilir. ${son} gününe kadar oynanmazsa kendiliğinden oynanır.</p>`}</section>`}
// ---------- ezeli rakip: meydan okuma ve ligde en çok karşılaşılan, skoru en yakın oyuncu (en az 3 maç). Derbi puanı hafta başındaki duruma göre sayılır ----------
