const ULT_SW={sut:{FV:1,OS:.5,DF:.18,KL:.02},ast:{FV:.45,OS:.65,DF:.3,KL:.06},kafa:{FV:.8,OS:.35,DF:.75,KL:0},orta:{FV:.4,OS:1,DF:.5,KL:0},sv:{FV:.6,OS:.9,DF:.25,KL:0},uzak:{FV:.4,OS:.9,DF:.35,KL:0}};
