function ultKpCift(K,r,s){if(r===1)return{a:K.players[2*s]||null,b:K.players[2*s+1]||null,ok:true};const x=ultKpKaz(K,r-1,2*s),y=ultKpKaz(K,r-1,2*s+1);return{a:x.w,b:y.w,ok:x.ok&&y.ok}}
