const ultHzDv=()=>Object.values(ULT_SRV.dv||{}).filter(d=>String(d.k).startsWith("hz|"));
const ultHzAcik=d=>!d.accepted_at&&!d.red_at&&ultNow()<Date.parse(d.created_at)+864e5;
