  const E=(ULT_SRV.ev||[]).filter(e=>e.kind==="hz"&&(e.a===me||e.b===me)&&e.p&&ultNow()-Date.parse(e.at||0)<864e5).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).slice(0,ULT.hzTum?10:3);
