    for(let j=1;j<7;j++){if(!A.cs[j]||j===tk)continue;if(j!==sh&&rl(A,j)==="DF"&&st<stayN){st++;F[j]=[F[j][0],48+jt()];continue}if(m==="sv"&&j!==sh&&rl(A,j)!=="FV"&&box.length>=2){continue}box.push(j)}
