        +it("odaReply","re","Yanıtla",`data-v="${x.id}"`)+it("odaCopy","cp","Kopyala",`data-v="${x.id}"`)
        +(mine?it("odaInfo","inf","Okundu bilgisi",`data-v="${x.id}"`):"")+(mine&&x.k==="msg"&&Date.now()-Date.parse(x.t)<3e5?it("odaEdit","ed","Düzenle",`data-v="${x.id}"`):"")
